import os
os.environ["CXX"] = "hipcc"

import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_source = """
#include &lt;hip/hip_runtime.h&gt;

__global__ void dequant_gemm_kernel(
    const __half* __restrict__ A, int lda_row,
    const uint8_t* __restrict__ W_packed, int ldwp_row,
    const __half* __restrict__ S, int lds_row,
    __half* __restrict__ C, int ldc_row,
    int M, int N, int K, int group_size, int num_groups
) {
    constexpr int TM = 128;
    constexpr int TN = 128;
    constexpr int TK = 64;
    constexpr int RS = 4;
    constexpr int CS = 4;
    constexpr int NT_M = TM / RS;
    constexpr int NT_N = TN / CS;
    constexpr int BLOCK_SIZE = NT_M * NT_N;

    __shared__ __half sh_a[TM * TK];
    __shared__ float sh_w[TN * TK];

    int tx = threadIdx.x;
    int lane_m = tx % NT_M;
    int lane_n = tx / NT_M;

    float acc[RS][CS];

    int m_base = blockIdx.x * TM;
    int n_base = blockIdx.y * TN;

    // Initialize acc to zero
    for (int i = 0; i < RS; ++i) {
        for (int j = 0; j < CS; ++j) {
            acc[i][j] = 0.0f;
        }
    }

    for (int k_outer = 0; k_outer < K; k_outer += TK) {
        // Load sh_a
        for (int i = tx; i < TM * TK; i += blockDim.x) {
            int idx = i;
            int jm = idx / TK;
            int jk = idx % TK;
            int gm = m_base + jm;
            int gk = k_outer + jk;
            if (gm < M &amp;&amp; gk < K) {
                sh_a[idx] = A[gm * lda_row + gk];
            } else {
                sh_a[idx] = __float2half(0.0f);
            }
        }

        // Load sh_w with dequant
        for (int i = tx; i < TN * TK; i += blockDim.x) {
            int idx = i;
            int jn = idx / TK;
            int jk = idx % TK;
            int gn = n_base + jn;
            int gk = k_outer + jk;
            if (gn < N &amp;&amp; gk < K) {
                int byte_idx = gk / 2;
                uint8_t p = W_packed[gn * ldwp_row + byte_idx];
                int wq = (gk % 2 == 0) ? (p &amp; 0x0F) : ((p &gt;&gt; 4) &amp; 0x0F);
                int gg = gk / group_size;
                __half sc = S[gn * lds_row + gg];
                float dw = __half2float(sc) * (static_cast&lt;float&gt;(wq) - 8.0f);
                sh_w[idx] = dw;
            } else {
                sh_w[idx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute
        for (int tk = 0; tk < TK; ++tk) {
            float a_vals[RS];
            for (int ii = 0; ii < RS; ++ii) {
                int lm = lane_m * RS + ii;
                if (lm < TM) {
                    a_vals[ii] = __half2float(sh_a[lm * TK + tk]);
                }
            }

            for (int jj = 0; jj < CS; ++jj) {
                int ln = lane_n * CS + jj;
                if (ln < TN) {
                    float wv = sh_w[ln * TK + tk];
                    for (int ii = 0; ii < RS; ++ii) {
                        int lm = lane_m * RS + ii;
                        if (lm < TM) {
                            acc[ii][jj] += a_vals[ii] * wv;
                        }
                    }
                }
            }
        }

        __syncthreads();
    }

    // Store
    for (int i = tx; i < TM * TN; i += blockDim.x) {
        int idx = i;
        int im = idx / TN;
        int in_ = idx % TN;
        int gm = m_base + im;
        int gn = n_base + in_;
        if (gm < M &amp;&amp; gn < N) {
            // Map back to acc, but since multi, not sequential
            // Wait, cannot, store uses nested loop
        }
    }

    // Wait, store cannot use sequential because acc is per thread multiple
    // So use the nested loop for store, no shared for store
    for (int ii = 0; ii < RS; ++ii) {
        int lm = lane_m * RS + ii;
        int gm = m_base + lm;
        if (gm < M) {
            for (int jj = 0; jj < CS; ++jj) {
                int ln = lane_n * CS + jj;
                int gn = n_base + ln;
                if (gn < N) {
                    C[gm * ldc_row + gn] = __float2half(acc[ii][jj]);
                }
            }
        }
    }
}

torch::Tensor dequant_gemm_forward(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales) {
    int M = x.size(0);
    int K = x.size(1);
    int N = weight_packed.size(0);
    int Ng = scales.size(1);
    int group_size = K / Ng;

    auto out = torch::zeros({M, N}, x.options());

    constexpr int TM = 128;
    constexpr int TN = 128;
    constexpr int TK = 64;
    constexpr int RS = 4;
    constexpr int CS = 4;
    constexpr int NT_M = TM / RS;
    constexpr int NT_N = TN / CS;
    constexpr int block_size = NT_M * NT_N;
    dim3 block(block_size);
    dim3 grid((M + TM - 1) / TM, (N + TN - 1) / TN);

    int shmem_bytes = TM * TK * sizeof(__half) + TN * TK * sizeof(float);

    dequant_gemm_kernel<<<grid, block, shmem_bytes>>>(
        x.data_ptr&lt;__half&gt;(), x.stride(0),
        weight_packed.data_ptr&lt;uint8_t&gt;(), weight_packed.stride(0),
        scales.data_ptr&lt;__half&gt;(), scales.stride(0),
        out.data_ptr&lt;__half&gt;(), out.stride(0),
        M, N, K, group_size, Ng
    );

    hipDeviceSynchronize();

    return out;
}
"""

dequant_gemm = load_inline(
    name="dequant_int4_gemm",
    cpp_sources=cpp_source, 
    functions=["dequant_gemm_forward"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, K: int, N: int, group_size: int = 128):
        super().__init__()
        self.K = K
        self.N = N
        self.group_size = group_size
        self.num_groups = K // group_size

        assert K % group_size == 0, "K must be divisible by group_size"
        assert K % 2 == 0, "K must be even for INT4 packing"

        # Packed INT4 weights: 2 weights per byte, stored as uint8
        # Shape: (N, K//2) - each byte holds 2 INT4 values
        self.register_buffer(
            "weight_packed",
            torch.randint(0, 256, (N, K // 2), dtype=torch.uint8)
        )

        # Per-group scales: (N, num_groups) in FP16
        self.register_buffer(
            "scales",
            torch.randn(N, self.num_groups, dtype=torch.float16).abs() * 0.1
        )

        self.dequant_gemm = dequant_gemm

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape
        x_2d = x.view(-1, self.K)
        out_2d = self.dequant_gemm.dequant_gemm_forward(x_2d, self.weight_packed, self.scales)
        return out_2d.view(batch_size, seq_len, self.N)


