                            acc[ii][jj] += av * wv;
                        }
                    }
                }
            }
        }
    }

    // Store
#pragma unroll
    for (int ii = 0; ii < RS; ++ii) {
        int lm = lane_m * RS + ii;
        int gm = m_base + lm;
        if (gm < M) {
#pragma unroll
            for (int jj = 0; jj < CS; ++jj) {
                int ln = lane_n * CS + jj;
                int gn = n_base + ln;
                if (gn < N) {
                    C[gm * ldc_row + gn] = __float2half(acc[ii][jj]);
                }
            }
        }
    }
